/**
 * @name User-controlled path to filesystem backends
 * @description Detect flow of remote inputs into fsspec filesystem implementations (open, mkdir, rm, etc.)
 * @kind path-problem
 * @problem.severity error
 * @id py/fsspec/user-controlled-path
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module FSSpecPathConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::moduleImport("fsspec").getMember(["open", "open_files"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module FSSpecPathFlow = TaintTracking::Global<FSSpecPathConfig>;
import FSSpecPathFlow::PathGraph

from FSSpecPathFlow::PathNode source, FSSpecPathFlow::PathNode sink
where FSSpecPathFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User data flows into fsspec path argument $@.", source.getNode(), "user input"
